// The Portfolio sheet gives one row per holding. Collapse them into a single
// item carrying every ticker, so MarketStack gets called once and not N times.
const holdings = $input.all()
  .map((item) => item.json)
  .filter((h) => h.ticker !== undefined && h.ticker !== null && String(h.ticker).trim() !== '');

if (holdings.length === 0) {
  throw new Error('No rows with a "ticker" column in the Portfolio sheet.');
}

const symbols = holdings.map((h) => String(h.ticker).trim().toUpperCase()).join(',');

return [{ json: { symbols, holdings } }];

// Join MarketStack closes onto the portfolio and work out how far each holding
// has drifted from its target weight.
const DRIFT_THRESHOLD = 0.05; // rebalance once a holding is 5 percentage points off

const holdings = $('Build Ticker List').first().json.holdings;
const rows = $input.first().json.data || [];

if (rows.length === 0) {
  throw new Error('MarketStack returned no price data. Check the access key and the symbols.');
}

const priceBySymbol = {};
let asOf = null;
for (const row of rows) {
  priceBySymbol[row.symbol] = row.close;
  if (!asOf && row.date) asOf = String(row.date).slice(0, 10);
}

const positions = holdings.map((h) => {
  const ticker = String(h.ticker).trim().toUpperCase();
  const price = priceBySymbol[ticker];
  if (price === undefined) {
    throw new Error(`MarketStack returned no price for ${ticker}.`);
  }
  const shares = Number(h.shares);
  const target = Number(h.target_weight);
  if (Number.isNaN(shares) || Number.isNaN(target)) {
    throw new Error(`Bad shares or target_weight for ${ticker}.`);
  }
  return { ticker, name: h.name || ticker, shares, price, value: shares * price, target_weight: target };
});

const total = positions.reduce((sum, p) => sum + p.value, 0);
if (total <= 0) {
  throw new Error('Portfolio total value is zero — check the shares column.');
}

const priced = positions.map((p) => {
  const currentWeight = p.value / total;
  const drift = currentWeight - p.target_weight;
  const targetValue = total * p.target_weight;
  const sharesDelta = Math.round((targetValue - p.value) / p.price);
  const action = Math.abs(drift) > DRIFT_THRESHOLD ? (sharesDelta > 0 ? 'BUY' : 'SELL') : 'HOLD';
  return {
    date: asOf,
    ticker: p.ticker,
    name: p.name,
    price: Number(p.price.toFixed(2)),
    shares: p.shares,
    current_value: Number(p.value.toFixed(2)),
    current_weight_pct: Number((currentWeight * 100).toFixed(2)),
    target_weight_pct: Number((p.target_weight * 100).toFixed(2)),
    drift_pts: Number((drift * 100).toFixed(2)),
    action,
    shares_delta: action === 'HOLD' ? 0 : sharesDelta,
  };
});

const needsRebalance = priced.some((p) => p.action !== 'HOLD');

const summary = [
  `Portfolio as of ${asOf}. Total value ${total.toFixed(2)}.`,
  `Drift threshold ${(DRIFT_THRESHOLD * 100).toFixed(0)} percentage points.`,
  '',
  ...priced.map(
    (p) =>
      `${p.ticker}: ${p.shares} @ ${p.price} = ${p.current_value} ` +
      `(${p.current_weight_pct}% vs target ${p.target_weight_pct}%, drift ${p.drift_pts} pts) ` +
      `-> ${p.action} ${p.shares_delta}`,
  ),
].join('\n');

return [{
  json: {
    as_of: asOf,
    total_value: Number(total.toFixed(2)),
    needs_rebalance: needsRebalance,
    summary_text: summary,
    positions: priced,
  },
}];

// One row per holding for the Rebalance Log sheet.
const drift = $('Compute Drift').first().json;
return drift.positions.map((p) => ({ json: p }));
